function findHeadingIndex(markdown, headingLine) {
  const re = new RegExp(`^${headingLine.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&")}\\s*$`, "m");
  const m = markdown.match(re);
  return m ? m.index : -1;
}

function parseEmails(markdown) {
  const start = findHeadingIndex(markdown, "## Email Excerpts");
  if (start < 0) return [];

  const end = findHeadingIndex(markdown, "## Policy Exceptions");
  const slice = end > start ? markdown.slice(start, end) : markdown.slice(start);

  const emails = [];
  const blocks = slice.split(/\n\n+/);
  for (const block of blocks) {
    const fromMatch = block.match(/^From:\s*(.+)$/im);
    const subjectMatch = block.match(/^Subject:\s*Re:\s*(TXN-[0-9a-f-]+)/im);
    const statusMatch = block.match(/^status:\s*(\w+)/im);
    if (!fromMatch || !subjectMatch || !statusMatch) continue;

    emails.push({
      from_addr: fromMatch[1].trim(),
      transaction_id: subjectMatch[1],
      status: statusMatch[1].trim().toLowerCase(),
    });
  }
  return emails;
}

module.exports = { parseEmails };
