function parseLedger(markdown) {
  const start = markdown.indexOf("## Transaction Ledger");
  if (start < 0) return [];

  // Only the section headed exactly '## Transaction Ledger' is authoritative.
  const slice = markdown.slice(start);

  const rowsById = new Map();
  const blocks = slice.split(/^### /m).slice(1);

  for (const block of blocks) {
    const lines = block.split("\n");
    const transactionId = lines[0].trim();
    if (!transactionId.startsWith("TXN-")) continue;

    // Brief 01: ignore any ledger block containing 'provisional: true' (case-insensitive).
    const isProvisional = lines.some((l) => /provisional\s*:\s*true/i.test(l));
    if (isProvisional) continue;

    const row = { transaction_id: transactionId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("amount:")) {
        row.amount = Number(trimmed.split(":")[1].trim());
      } else if (trimmed.startsWith("owner:")) {
        row.owner = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("status:")) {
        row.status = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("date:")) {
        row.date = trimmed.split(":")[1].trim();
      }
    }

    // If duplicates appear, prefer the later non-provisional block (deterministic, file-order).
    rowsById.set(transactionId, row);
  }

  return [...rowsById.values()];
}

module.exports = { parseLedger };
EOF
