const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function toCentsNumber(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return 0;
  return Math.round(x * 100) / 100;
}

function reconcileTransactions(parsed) {
  const byId = new Map();
  for (const row of parsed.ledger || []) {
    byId.set(row.transaction_id, { ...row });
  }

  // Meeting amendments (Brief 05): only signed amendments affect owner.
  for (const meeting of parsed.meetings || []) {
    if (!meeting || !meeting.transaction_id) continue;
    if (!meeting.signed) continue;
    const target = byId.get(meeting.transaction_id);
    if (target && meeting.owner) target.owner = meeting.owner;
  }

  // Email excerpts (Brief 02): may change status only when From contains 'compliance@'.
  for (const email of parsed.emails || []) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;
    if (!email.status) continue;
    if (!String(email.from_addr || "").includes("compliance@")) continue;

    // Brief 02: status precedence from lowest to highest.
    const cur = String(target.status || "pending").toLowerCase();
    const next = String(email.status).toLowerCase();
    const curRank = STATUS_ORDER[cur] ?? -1;
    const nextRank = STATUS_ORDER[next] ?? -1;
    if (nextRank >= curRank) target.status = next;
  }

  // Corrections: apply deterministically by notice_id, and emit report rows.
  const report = [];
  const notices = [...(parsed.corrections || [])].sort((a, b) =>
    String(a.notice_id).localeCompare(String(b.notice_id)),
  );

  for (const notice of notices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const fieldMap = { owner: "owner", status: "status", date: "date" };
    const k = fieldMap[notice.field];
    if (!k) continue;

    const prev = target[k] == null ? "" : String(target[k]);
    target[k] = notice.value;

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: prev,
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  const policySet = parsed.policyExceptions instanceof Set ? parsed.policyExceptions : new Set();

  const items = sortByTransactionId(
    [...byId.values()].map((row) => {
      const flags = [];
      if (policySet.has(row.transaction_id)) flags.push("policy_exception");

      const exception_reason = flags.length ? flags.sort().join(";") : null;

      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status: String(row.status).toLowerCase(),
        effective_date: row.date,
        amount_usd: toCentsNumber(row.amount),
        exception_reason,
      };
    }),
  );

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
EOF
